import '../models/materi_content.dart';

/// Materi PPKn SMP Kelas 9.
const List<MateriSection> materiKelas9 = <MateriSection>[
  MateriSection(
    id: 'kelas9-materi-1',
    number: 1,
    title: 'Hubungan Pancasila Dengan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Bhinnekatunggal Ika, Dan Negara Kesatuan Republik Indonesia',
    summary: 'Ibarat sebuah rumah yang kokoh, Negara Indonesia membutuhkan pondasi, tiang, atap, dan pengikat agar tidak mudah runtuh saat diterpa badai. Dalam kehidupan berbangsa kita, "rumah" itu dibangun oleh Empat Pilar Kebangsaan: Pancasila, UUD NRI Tahun 1945, Bhinneka Tunggal Ika, dan Negara Kesatuan Republik Indonesia (NKRI). Keempatnya bukanlah hal yang terpisah, melainkan sebuah sistem yang saling menguatkan. Mari kita bedah satu per satu bagaimana Pancasila menjadi "jantung" yang menghubungkan semuanya, khusus untuk kamu siswa kelas IX!',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.heading, 'Semangat Pancasila dalam Kehidupan Bernegara'),
      MateriBlock(MateriBlockType.paragraph, 'Pancasila bukan sekadar teks yang dibacakan setiap upacara hari Senin. Pancasila adalah ideologi dan dasar negara. Artinya, cara kita berpikir, bertindak, dan membuat peraturan di Indonesia harus mencerminkan kelima sila tersebut. Mengapa semangat Pancasila ini sangat penting dalam kehidupan bernegara? Tanpa semangat Pancasila, negara kita yang sangat besar ini akan mudah kehilangan arah. Bayangkan jika pemerintah membuat jalan tol, tapi menggusur rumah warga tanpa ganti rugi yang adil. Itu berarti melanggar Sila Ke-2 (Kemanusiaan yang adil dan beradab) dan Sila Ke-5 (Keadilan sosial). Penerapan Semangat Pancasila di Berbagai Tingkatan:'),
      MateriBlock(MateriBlockType.bullet, 'Di tingkat negara: Pemerintah membuat kebijakan yang mengutamakan rakyat kecil (Sila ke-5), menghargai kebebasan beragama (Sila ke-1), dan menyelesaikan masalah politik melalui pemilu yang demokratis (Sila ke-4).'),
      MateriBlock(MateriBlockType.bullet, 'Di tingkat masyarakat: Gotong royong membersihkan lingkungan, membayar pajak tepat waktu, dan tidak menyebarkan hoax yang bisa memecah belah bangsa (Sila ke-3).'),
      MateriBlock(MateriBlockType.bullet, 'Di tingkat sekolah: Kamu berteman dengan siapa saja tanpa membedakan status sosial atau agama, berdiskusi saat kerja kelompok, dan menghormati guru.'),
      MateriBlock(MateriBlockType.paragraph, 'Pancasila adalah kompas. Sejauh apa pun Indonesia melangkah dan semodern apa pun teknologi nantinya, kompas ini memastikan kita tidak tersesat dari nilai-nilai luhur bangsa.'),
      MateriBlock(MateriBlockType.heading, 'Hubungan Pancasila dengan UUD NRI Tahun 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Jika Pancasila adalah "ruh" atau "nyawa" dari negara kita, maka Undang-Undang Dasar (UUD) NRI Tahun 1945 adalah "raga" atau "pakaian"-nya. UUD 1945 adalah hukum dasar tertulis tertinggi di Indonesia. Hubungan keduanya sangat erat dan tidak bisa dipisahkan, ibarat dua sisi mata uang. Berikut adalah poin-poin penting hubungannya:'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila adalah Sumber dari Segala Sumber Hukum'),
      MateriBlock(MateriBlockType.paragraph, 'Tidak boleh ada satu pun pasal dalam UUD 1945 (bahkan undang-undang di bawahnya seperti UU Lalu Lintas atau UU ITE) yang bertentangan dengan Pancasila. Jika ada aturan yang tidak adil atau menindas, aturan tersebut harus dihapus karena melanggar Pancasila.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Terdapat di dalam UUD 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Coba buka kembali naskah Pembukaan UUD 1945. Pada alinea keempat, rumusan kelima sila Pancasila tertulis secara resmi dan sah. Karena Pembukaan UUD 1945 memuat dasar negara (Pancasila) dan tujuan negara, maka Pembukaan UUD 1945 bersifat tetap, abadi, dan tidak boleh diubah oleh siapa pun, termasuk oleh MPR. Mengubah Pembukaan UUD 1945 sama artinya dengan membubarkan negara Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Dijabarkan Melalui Pasal-Pasal UUD 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Nilai-nilai Pancasila yang masih umum, diperinci menjadi aturan yang lebih jelas di pasal-pasal UUD 1945.'),
      MateriBlock(MateriBlockType.bullet, 'Contoh: Sila ke-1 (Ketuhanan Yang Maha Esa) dijabarkan dalam Pasal 29 UUD 1945 yang menjamin kemerdekaan tiap penduduk untuk memeluk agama dan beribadah.'),
      MateriBlock(MateriBlockType.bullet, 'Contoh: Sila ke-4 (Kerakyatan) dijabarkan dalam pasal-pasal tentang Pemilihan Umum dan keanggotaan DPR/MPR.'),
      MateriBlock(MateriBlockType.heading, 'Hubungan Pancasila dengan Bhinneka Tunggal Ika'),
      MateriBlock(MateriBlockType.paragraph, 'Bhinneka Tunggal Ika yang tertulis pada pita di cengkeraman burung Garuda memiliki arti "Berbeda-beda tetapi tetap satu jua". Indonesia adalah salah satu negara paling beragam di dunia. Kita punya lebih dari 1.300 suku bangsa, 700 bahasa daerah, serta berbagai agama dan kepercayaan. Perbedaan ini bisa menjadi kekayaan, tapi juga bisa menjadi bom waktu yang memicu konflik (seperti tawuran antar-kampung atau perang antar-suku). Di sinilah peran Pancasila:'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila sebagai Tali Pengikat: Bhinneka Tunggal Ika adalah fakta/kenyataan keberagaman kita, sedangkan Pancasila adalah alat pemersatunya. Sila ke-3, Persatuan Indonesia, memerintahkan kita untuk menempatkan kepentingan bangsa di atas kepentingan suku atau golongan pribadi.'),
      MateriBlock(MateriBlockType.bullet, 'Mencegah Mayoritas Menindas Minoritas: Pancasila memastikan bahwa kelompok yang jumlahnya lebih besar tidak boleh semena-mena terhadap kelompok yang lebih kecil. Semua warga negara punya hak yang sama di mata hukum.'),
      MateriBlock(MateriBlockType.bullet, 'Toleransi Sehari-hari: Saat kamu membiarkan temanmu yang berbeda agama untuk beribadah di tengah-tengah kerja kelompok, kamu sedang mempraktikkan Bhinneka Tunggal Ika yang dijiwai oleh Pancasila (Sila ke-1 dan ke-2).'),
      MateriBlock(MateriBlockType.paragraph, 'Singkatnya: Bhinneka Tunggal Ika menyadarkan kita bahwa kita ini beda-beda, dan Pancasila memberi tahu kita bagaimana caranya hidup rukun di tengah perbedaan tersebut.'),
      MateriBlock(MateriBlockType.heading, 'Hubungan Pancasila dengan Negara Kesatuan Republik Indonesia (NKRI)'),
      MateriBlock(MateriBlockType.paragraph, 'NKRI adalah bentuk fisik dari negara kita, mulai dari Sabang sampai Merauke, Miangas sampai Pulau Rote. Bentuk negara kita adalah "Kesatuan" (bukan serikat/federal seperti Amerika Serikat). Artinya, kekuasaan tertinggi berada di tangan pemerintah pusat, meskipun daerah diberi kebebasan untuk mengurus wilayahnya sendiri (otonomi daerah). Lalu, apa hubungannya dengan Pancasila?'),
      MateriBlock(MateriBlockType.bullet, 'NKRI adalah Wadah, Pancasila adalah Isinya'),
      MateriBlock(MateriBlockType.paragraph, 'Bentuk negaranya adalah NKRI, sementara ideologi yang mengisi dan menggerakkan wadah tersebut adalah Pancasila. Tanpa Pancasila, wilayah Indonesia yang terpisah-pisah oleh lautan ini mungkin sudah lama terpecah belah dan membentuk negara-negara kecil sendiri.'),
      MateriBlock(MateriBlockType.bullet, 'Menangkal Paham Separatisme'),
      MateriBlock(MateriBlockType.paragraph, 'Terkadang ada kelompok di daerah tertentu yang ingin memisahkan diri dari Indonesia (separatisme). Semangat Pancasila, khususnya Sila ke-3 (Persatuan Indonesia) dan Sila ke-5 (Keadilan Sosial), menjadi kunci untuk menjaga NKRI. Jika pemerintah menerapkan keadilan sosial, membangun jalan, sekolah, dan rumah sakit yang bagus tidak hanya di Pulau Jawa, tetapi juga di Papua, Kalimantan, dan pulau terluar lainnya, maka seluruh rakyat akan merasa diperhatikan. Rasa adil inilah yang membuat masyarakat ingin terus bersatu di dalam NKRI.'),
      MateriBlock(MateriBlockType.bullet, 'Bela Negara Kapan Saja'),
      MateriBlock(MateriBlockType.paragraph, 'Menjaga NKRI bukan cuma tugas TNI atau polisi. Sebagai pelajar Kelas IX, kamu menjaga NKRI dan mengamalkan Pancasila dengan cara: belajar dengan giat agar bisa memajukan bangsa, mencintai produk dalam negeri, dan berprestasi membawa nama Indonesia di kancah internasional (seperti olimpiade sains atau olahraga).'),
      MateriBlock(MateriBlockType.paragraph, 'Empat hal ini tidak bisa dipisahkan. NKRI adalah rumah fisiknya. UUD 1945 adalah aturan main di dalam rumah tersebut. Bhinneka Tunggal Ika adalah sifat dari orang-orang yang tinggal di dalam rumah itu (beragam tapi satu keluarga). Dan Pancasila adalah pondasi serta ruh yang memastikan rumah tersebut berdiri kokoh, rukun, dan punya tujuan yang jelas. Memahami hubungan keempatnya bukan hanya untuk modal ujian PPKn, tapi merupakan bekal kamu sebagai generasi penerus bangsa.'),
    ],
  ),
  MateriSection(
    id: 'kelas9-materi-2',
    number: 2,
    title: 'Hak Dan Kewajiban Warga Negara',
    summary: '',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.heading, 'Bayangkan kamu membeli tiket untuk masuk ke sebuah taman hiburan. Kamu berhak menikmati semua wahana, mendapat fasilitas toilet yang bersih, dan merasa aman selama bermain. Namun, kamu juga memiliki kewajiban: harus membayar tiket masuk, mengantre dengan tertib, dan membuang sampah pada tempatnya. Konsep sederhana di taman hiburan tersebut adalah cerminan dari bagaimana kita hidup sebagai warga negara di Indonesia.'),
      MateriBlock(MateriBlockType.heading, 'Hak dan Kewajiban'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam kehidupan bernegara, kita harus memahami perbedaan antara hak dan kewajiban, serta bedanya dengan hak asasi:'),
      MateriBlock(MateriBlockType.bullet, 'Hak Warga Negara adalah segala sesuatu yang pantas, mutlak, dan sah untuk didapatkan oleh seseorang sebagai anggota dari sebuah negara. Hak ini dibatasi oleh status kewarganegaraan. (Contoh: Warga Negara Asing/WNA yang tinggal di Indonesia tidak berhak ikut mencoblos dalam Pemilu).'),
      MateriBlock(MateriBlockType.bullet, 'Kewajiban Warga Negara adalah tindakan atau sikap yang harus dilakukan oleh warga negara dengan penuh tanggung jawab sesuai dengan peraturan perundang-undangan yang berlaku.'),
      MateriBlock(MateriBlockType.bullet, 'Catatan penting: Ini berbeda dengan Hak Asasi Manusia (HAM). HAM melekat pada setiap manusia sejak lahir, tidak peduli dari negara mana ia berasal (seperti hak untuk hidup). Semua hak asasi adalah hak warga negara, tetapi tidak semua hak warga negara adalah hak asasi.'),
      MateriBlock(MateriBlockType.heading, 'Pelaksanaan Hak dan Kewajiban Warga Negara secara Seimbang'),
      MateriBlock(MateriBlockType.paragraph, 'Hak dan kewajiban ibarat dua sisi dari satu koin yang sama. Keduanya tidak bisa dipisahkan dan harus dijalankan secara seimbang. Kamu tidak bisa terus-menerus menuntut hak jika kamu sendiri mengabaikan kewajibanmu. Prinsip utama dari keseimbangan ini adalah: "Hakmu dibatasi oleh hak orang lain." Di negara demokrasi, kebebasan kita bukanlah kebebasan tanpa batas. Berikut adalah contoh penerapan keseimbangan tersebut dalam kehidupan sehari-hari:'),
      MateriBlock(MateriBlockType.bullet, 'Di rumah: Kamu berhak mendapat kasih sayang dari orang tua, tapi kamu wajib menghormati mereka dan membantu pekerjaan rumah.'),
      MateriBlock(MateriBlockType.bullet, 'Di sekolah: Kamu berhak mendapatkan pengajaran yang baik dari guru dan fasilitas kelas yang layak, tetapi kamu wajib menaati tata tertib sekolah, mengerjakan tugas, dan tidak merusak meja/kursi.'),
      MateriBlock(MateriBlockType.bullet, 'Di lingkungan masyarakat: Kamu berhak mendengarkan musik favoritmu. Namun, jika kamu menyalakannya menggunakan speaker besar pada jam 11 malam, kamu telah melanggar hak tetanggamu untuk beristirahat dengan tenang.'),
      MateriBlock(MateriBlockType.heading, 'Hak dan Kewajiban Warga Negara dalam UUD NRI Tahun 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai hukum dasar tertinggi, UUD 1945 secara tegas mengatur apa saja yang menjadi hak dan kewajiban kita. Jika pemerintah gagal memberikan hak ini, atau jika rakyat menolak menjalankan kewajibannya, maka ada sanksi hukum yang berlaku. Berikut adalah pasal-pasal kunci yang mengatur hak dan kewajiban kita:'),
      MateriBlock(MateriBlockType.heading, 'Pasal UUD 1945'),
      MateriBlock(MateriBlockType.heading, 'Hak Warga Negara'),
      MateriBlock(MateriBlockType.heading, 'Kewajiban Warga Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 27 ayat (1)'),
      MateriBlock(MateriBlockType.paragraph, 'Diperlakukan sama di hadapan hukum dan pemerintahan.'),
      MateriBlock(MateriBlockType.paragraph, 'Wajib menjunjung tinggi hukum dan pemerintahan tanpa pengecualian.'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 27 ayat (2)'),
      MateriBlock(MateriBlockType.paragraph, 'Mendapat pekerjaan dan penghidupan yang layak.'),
      MateriBlock(MateriBlockType.paragraph, '(Fokus pasal ini adalah pada pemenuhan hak oleh negara)'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 27 ayat (3)'),
      MateriBlock(MateriBlockType.paragraph, 'Berhak ikut serta dalam upaya pembelaan negara.'),
      MateriBlock(MateriBlockType.paragraph, 'Wajib ikut serta dalam upaya pembelaan negara.'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 28 dan 28E'),
      MateriBlock(MateriBlockType.paragraph, 'Kebebasan berserikat, berkumpul, dan mengeluarkan pendapat.'),
      MateriBlock(MateriBlockType.paragraph, 'Menghargai pendapat orang lain dan tidak menyebarkan fitnah/hoaks.'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 29 ayat (2)'),
      MateriBlock(MateriBlockType.paragraph, 'Kemerdekaan untuk memeluk agama dan beribadah.'),
      MateriBlock(MateriBlockType.paragraph, 'Menghormati agama dan kepercayaan orang lain (Toleransi).'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 31 ayat (1) & (2)'),
      MateriBlock(MateriBlockType.paragraph, 'Berhak mendapat pendidikan.'),
      MateriBlock(MateriBlockType.paragraph, 'Wajib mengikuti pendidikan dasar (SD-SMP) dan negara wajib membiayainya.'),
      MateriBlock(MateriBlockType.paragraph, 'Pasal 23A'),
      MateriBlock(MateriBlockType.paragraph, 'Menikmati fasilitas umum (jalan, jembatan) hasil dari pajak.'),
      MateriBlock(MateriBlockType.paragraph, 'Wajib membayar pajak dan pungutan resmi lainnya kepada negara.'),
      MateriBlock(MateriBlockType.heading, 'Tantangan Pemenuhan Hak dan Kewajiban Warga Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Meskipun aturannya sudah tertulis jelas di UUD 1945, pada praktiknya kita masih sering melihat Pelanggaran Hak (seperti perundungan di sekolah, anak putus sekolah karena biaya) dan Pengingkaran Kewajiban (seperti mencontek, membuang sampah di sungai, tidak membayar pajak). Tantangan ini muncul dari dua faktor utama:'),
      MateriBlock(MateriBlockType.numberedItem, '1. Faktor Internal (Dari dalam diri)'),
      MateriBlock(MateriBlockType.bullet, 'Sikap Egois yang Berlebihan: Seseorang yang selalu menuntut haknya dipenuhi, tetapi sengaja melupakan kewajibannya terhadap orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Rendahnya Kesadaran Berbangsa: Sikap meremehkan hukum. Contoh sederhananya adalah pelajar yang berkendara tanpa helm atau menerobos lampu merah karena merasa "tidak ada polisi yang melihat".'),
      MateriBlock(MateriBlockType.bullet, 'Sikap Tidak Toleran: Perasaan bahwa kelompok, ras, atau agamanya paling benar, sehingga memicu tindakan diskriminasi yang merampas hak orang lain.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Faktor Eksternal (Dari luar/lingkungan)'),
      MateriBlock(MateriBlockType.bullet, 'Ketidaktegasan Aparat Penegak Hukum: Jika pelanggar aturan tidak ditindak dengan tegas dan adil, masyarakat akan kehilangan rasa hormat terhadap hukum dan cenderung mengulangi pelanggaran tersebut.'),
      MateriBlock(MateriBlockType.bullet, 'Penyalahgunaan Kekuasaan: Korupsi yang dilakukan oleh pejabat negara adalah bentuk nyata perampasan hak rakyat. Dana yang seharusnya untuk membangun sekolah atau puskesmas justru masuk ke kantong pribadi.'),
      MateriBlock(MateriBlockType.bullet, 'Penyalahgunaan Teknologi: Internet dan media sosial memberikan kebebasan berekspresi, namun sering disalahgunakan untuk cyberbullying, penipuan daring, atau menyebarkan ujaran kebencian yang melanggar hak orang lain untuk merasa aman.'),
      MateriBlock(MateriBlockType.paragraph, 'Menjaga keseimbangan antara hak dan kewajiban bukanlah tugas yang bisa diselesaikan oleh presiden atau polisi saja. Negara yang damai, maju, dan tertib selalu dimulai dari ruang kelasmu, dari bagaimana kamu menghargai teman sebangkumu, dan dari kedisiplinanmu mematuhi aturan-aturan kecil setiap harinya.'),
