  MateriSection(
    id: 'kelas9-materi-3',
    number: 3,
    title: 'Kemerdekaan Berpendapat Warga Negara Pada Era Keterbukaan Informasi',
    summary: 'Pernahkah kamu merasa tidak setuju dengan aturan baru di sekolah, atau merasa punya ide brilian untuk acara class meeting namun takut untuk menyampaikannya? Di negara demokrasi seperti Indonesia, bersuara bukanlah sebuah kesalahan, melainkan sebuah hak yang dijamin oleh konstitusi. Mari kita pelajari bagaimana cara menyuarakan pikiranmu dengan benar, aman, dan berdampak di era di mana informasi mengalir begitu cepat!',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.heading, 'Makna Kemerdekaan Berpendapat Warga Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Kemerdekaan berpendapat adalah hak setiap warga negara untuk menyampaikan pikiran, gagasan, atau kritiknya, baik secara lisan maupun tulisan, secara bebas dan bertanggung jawab tanpa adanya tekanan dari pihak mana pun. Kebebasan ini adalah "oksigen" bagi negara demokrasi. Tanpa kebebasan berpendapat, pemerintah bisa bertindak semena-mena karena tidak ada rakyat yang berani mengawasi atau mengkritik. Di sekolah, kebebasan berpendapat terlihat saat kamu berani mengangkat tangan di kelas untuk menyanggah jawaban temanmu, atau saat pengurus OSIS mengusulkan program baru kepada kepala sekolah.'),
      MateriBlock(MateriBlockType.paragraph, 'Namun, ada kata kunci penting di sini: Bebas dan Bertanggung Jawab. Bebas bukan berarti kamu boleh berkata kasar, menyebarkan fitnah, atau menghina orang lain. Pendapatmu harus memiliki dasar yang kuat dan disampaikan dengan cara yang beradab.'),
      MateriBlock(MateriBlockType.heading, 'Jaminan Kemerdekaan Berpendapat di Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai warga negara, kamu tidak perlu takut untuk bersuara karena negara secara resmi melindunginya melalui hukum dasar kita. Dasar hukum utamanya adalah:'),
      MateriBlock(MateriBlockType.bullet, 'UUD NRI Tahun 1945 Pasal 28: "Kemerdekaan berserikat dan berkumpul, mengeluarkan pikiran dengan lisan dan tulisan dan sebagainya ditetapkan dengan undang-undang."'),
      MateriBlock(MateriBlockType.bullet, 'UUD NRI Tahun 1945 Pasal 28E Ayat (3): "Setiap orang berhak atas kebebasan berserikat, berkumpul, dan mengeluarkan pendapat."'),
      MateriBlock(MateriBlockType.bullet, 'Undang-Undang No. 9 Tahun 1998: Undang-undang ini secara khusus mengatur tentang Kemerdekaan Menyampaikan Pendapat di Muka Umum.'),
      MateriBlock(MateriBlockType.paragraph, 'Meskipun dijamin kuat, hukum kita juga menetapkan batasannya. Kebebasanmu berpendapat akan berhenti ketika pendapat tersebut mulai melanggar hak orang lain, mengganggu ketertiban umum, melanggar nilai moral/agama, atau mengancam keutuhan Negara Kesatuan Republik Indonesia (NKRI).'),
      MateriBlock(MateriBlockType.heading, 'Bentuk-Bentuk Penyampaian Pendapat'),
      MateriBlock(MateriBlockType.paragraph, 'Seiring berjalannya waktu, cara orang menyampaikan pendapat semakin beragam. Secara umum, bentuk penyampaian pendapat dibagi menjadi tiga jalur:'),
      MateriBlock(MateriBlockType.bullet, 'Secara Lisan: Menyampaikan langsung dengan suara. Contohnya adalah berpidato, melakukan wawancara, atau berdiskusi di forum kelas.'),
      MateriBlock(MateriBlockType.bullet, 'Secara Tulisan: Menyampaikan melalui teks atau gambar. Contohnya adalah menulis artikel di mading sekolah, membuat petisi, membentangkan spanduk, hingga membuat cuitan/postingan di media sosial.'),
      MateriBlock(MateriBlockType.heading, 'Di Muka Umum (Aksi Massa):'),
      MateriBlock(MateriBlockType.bullet, 'Unjuk rasa / Demonstrasi: Kegiatan yang dilakukan oleh seorang atau kelompok untuk menyampaikan pikiran secara lisan/tulisan di tempat umum. Aksi ini wajib dilakukan secara damai, tidak merusak fasilitas umum (anarkis), dan harus memberitahukan pihak kepolisian terlebih dahulu.'),
      MateriBlock(MateriBlockType.bullet, 'Pawai: Cara penyampaian pendapat dengan arak-arakan di jalan umum.'),
      MateriBlock(MateriBlockType.bullet, 'Mimbar bebas: Kegiatan menyampaikan pendapat di tempat terbuka yang disediakan secara khusus.'),
      MateriBlock(MateriBlockType.heading, 'Keterbukaan Informasi Publik'),
      MateriBlock(MateriBlockType.paragraph, 'Bagaimana kamu bisa memberikan pendapat atau kritik yang bagus jika kamu tidak tahu apa yang sedang terjadi? Di sinilah pentingnya Keterbukaan Informasi Publik (KIP). Keterbukaan informasi berarti pemerintah (sebagai badan publik) wajib membuka akses informasi terkait kebijakan, anggaran, dan program kerja mereka kepada rakyat. Hal ini diatur kuat dalam UU No. 14 Tahun 2008. Mengapa Keterbukaan Informasi ini sangat penting?'),
      MateriBlock(MateriBlockType.bullet, 'Mencegah Korupsi: Jika rakyat bisa melihat laporan keuangan daerah, pejabat akan takut untuk mencuri uang negara.'),
      MateriBlock(MateriBlockType.bullet, 'Meningkatkan Partisipasi Rakyat: Rakyat yang mendapat informasi utuh bisa memberikan masukan dan pendapat yang solutif untuk pembangunan negara.'),
      MateriBlock(MateriBlockType.bullet, 'Membangun Kepercayaan: Pemerintah yang transparan akan lebih dipercaya oleh warganya.'),
      MateriBlock(MateriBlockType.paragraph, 'Namun, tidak semua informasi boleh dibuka. Pemerintah berhak merahasiakan informasi yang berkaitan dengan strategi pertahanan negara, rahasia intelijen, atau data pribadi warga negara yang bersifat privasi.'),
      MateriBlock(MateriBlockType.heading, 'Praktik Mengemukakan Pendapat (Terutama di Era Digital)'),
      MateriBlock(MateriBlockType.paragraph, 'Era digital dan media sosial membuat siapa saja, termasuk kamu yang masih SMP, bisa berbicara kepada dunia hanya dengan bermodal smartphone. Cuitan atau videomu bisa viral dan ditonton jutaan orang dalam hitungan jam. Ini adalah kemerdekaan berpendapat tingkat tinggi. Namun, kebebasan besar datang dengan tanggung jawab yang besar. Berikut adalah praktik dan etika mengemukakan pendapat yang benar di era keterbukaan informasi:'),
      MateriBlock(MateriBlockType.bullet, 'Saring Sebelum Sharing'),
      MateriBlock(MateriBlockType.paragraph, 'Sebelum berpendapat mengomentari sebuah berita, pastikan berita itu benar (bukan hoaks). Berpendapat berdasarkan informasi palsu hanya akan mempermalukan dirimu sendiri dan memicu kegaduhan.'),
      MateriBlock(MateriBlockType.bullet, 'Gunakan Bahasa yang Beradab'),
      MateriBlock(MateriBlockType.paragraph, 'Hindari kata-kata makian, cacian, atau body shaming. Kritiklah ide atau tindakannya, bukan menyerang fisik atau latar belakang orangnya.'),
      MateriBlock(MateriBlockType.bullet, 'Hindari Isu SARA'),
      MateriBlock(MateriBlockType.paragraph, 'Jangan pernah menyampaikan pendapat yang berisi ujaran kebencian (hate speech) atau merendahkan Suku, Agama, Ras, dan Antargolongan tertentu. Ini bukan hanya tidak etis, tapi juga bisa membuatmu dipenjara karena melanggar hukum.'),
      MateriBlock(MateriBlockType.bullet, 'Siap Menerima Perbedaan'),
      MateriBlock(MateriBlockType.paragraph, 'Ketika kamu melempar pendapatmu ke publik (misalnya di kolom komentar Instagram), kamu harus siap jika ada orang yang tidak setuju. Berdebatlah dengan sehat, dan jangan marah jika pendapatmu dipatahkan oleh argumen yang lebih logis.'),
      MateriBlock(MateriBlockType.bullet, 'Pahami Batasan Hukum (UU ITE)'),
      MateriBlock(MateriBlockType.paragraph, 'Jejak digital itu abadi. Indonesia memiliki Undang-Undang Informasi dan Transaksi Elektronik (UU ITE) yang mengatur larangan penyebaran berita bohong, pencemaran nama baik, dan ancaman kekerasan di dunia maya. Berpikirlah dua kali sebelum memencet tombol post atau send.'),
      MateriBlock(MateriBlockType.paragraph, 'Kemerdekaan berpendapat adalah hak istimewa yang diperjuangkan dengan susah payah oleh para pendiri bangsa ini. Gunakan hakmu dengan cerdas untuk membawa perubahan yang positif, baik untuk sekolahmu, lingkunganmu, maupun negara Indonesia.'),
    ],
  ),
  MateriSection(
    id: 'kelas9-materi-4',
    number: 4,
    title: 'Menjaga Dan Melestarikan Tradisi, Kearifan Lokal, Serta Budaya Dalam Masyarakat Global',
    summary: 'Di era ini, kamu bisa menonton konser K-Pop secara live dari kamar, memesan barang online dari negara lain, atau mengadopsi gaya hidup ala Barat dengan sangat mudah. Pertanyaannya: Bagaimana kita bisa menjadi "warga dunia" yang modern, tanpa kehilangan akar identitas kita sebagai orang Indonesia? Mari kita kupas satu per satu.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.heading, 'Makna Tradisi, Kearifan Lokal, dan Budaya'),
      MateriBlock(MateriBlockType.paragraph, 'Ketiga kata ini sering diucapkan bersamaan, namun sebenarnya memiliki makna dan fungsi yang berbeda. Ibarat sebuah pohon besar, ketiganya saling melengkapi agar pohon tersebut bisa berdiri kokoh dan berbuah.'),
      MateriBlock(MateriBlockType.bullet, 'Budaya (Pohon Keseluruhan)'),
      MateriBlock(MateriBlockType.paragraph, 'Budaya adalah segala sesuatu yang diciptakan oleh akal budi manusia untuk bertahan hidup dan membuat hidup lebih baik. Budaya sangat luas cakupannya. Ia meliputi bahasa yang kita pakai, bentuk rumah adat, pakaian, seni tari, makanan, hingga sistem kepercayaan dan hukum.'),
      MateriBlock(MateriBlockType.bullet, 'Tradisi (Cabang yang Tumbuh Lintas Generasi)'),
      MateriBlock(MateriBlockType.paragraph, 'Tradisi adalah kebiasaan, adat istiadat, atau ritual yang diwariskan secara turun-temurun dari nenek moyang dan masih terus dilakukan hingga hari ini. Tradisi adalah tindakan nyata (praktik) dari sebuah budaya. Contoh: Budaya masyarakat Jawa menghormati orang tua, tradisinya diwujudkan dalam bentuk sungkeman saat Lebaran.'),
      MateriBlock(MateriBlockType.bullet, 'Kearifan Lokal (Akar yang Memberi Nutrisi)'),
      MateriBlock(MateriBlockType.paragraph, 'Kearifan lokal (Local Wisdom) adalah nilai-nilai, filosofi, atau "kecerdasan tersembunyi" dari masyarakat setempat yang sudah teruji oleh waktu, biasanya digunakan untuk menjaga keseimbangan alam atau menyelesaikan konflik sosial. Kearifan lokal adalah inti pelajaran dari sebuah tradisi. Singkatnya: Budaya adalah payung besarnya, tradisi adalah cara kita mempraktikkannya berulang-ulang, dan kearifan lokal adalah kebijaksanaan di balik praktik tersebut.'),
      MateriBlock(MateriBlockType.heading, 'Contoh Tradisi, Kearifan Lokal, dan Budaya di Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Untuk memahaminya lebih jauh, mari kita lihat contoh-contoh nyata yang tidak hanya hidup, tapi juga diakui oleh dunia.'),
      MateriBlock(MateriBlockType.numberedItem, '1. Budaya: Wayang Kulit (Jawa)'),
      MateriBlock(MateriBlockType.paragraph, 'Wayang kulit bukan sekadar pertunjukan boneka bayangan. Ia adalah produk budaya yang sangat kompleks. Di dalamnya terdapat seni pahat (pembuatan wayang dari kulit kerbau), seni musik (gamelan), dan seni sastra (cerita epik Ramayana/Mahabharata). Lebih dari itu, Wayang adalah sarana pendidikan moral. Saking tingginya nilai budaya ini, UNESCO (Badan PBB untuk Pendidikan dan Kebudayaan) menetapkan Wayang Kulit sebagai Masterpiece of the Oral and Intangible Heritage of Humanity.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Tradisi: Rambu Solo\' (Tana Toraja, Sulawesi Selatan)'),
      MateriBlock(MateriBlockType.paragraph, 'Rambu Solo\' adalah upacara pemakaman adat di Toraja yang sangat megah dan bisa memakan waktu berhari-hari. Keluarga yang ditinggalkan akan menyembelih puluhan kerbau dan babi sebagai bentuk penghormatan terakhir kepada keluarga yang meninggal. Meskipun terlihat seperti pemborosan bagi orang luar, tradisi ini sebenarnya mengajarkan nilai gotong royong tingkat tinggi, kekeluargaan yang erat, serta penghormatan absolut kepada leluhur.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Kearifan Lokal: Hutan Larangan (Kampung Naga, Tasikmalaya)'),
      MateriBlock(MateriBlockType.paragraph, 'Masyarakat adat Kampung Naga di Jawa Barat memiliki kearifan lokal berupa Leuweung Larangan (Hutan Larangan). Tidak ada satu pun warga yang boleh masuk, menebang pohon, atau berburu di hutan tersebut karena dianggap keramat (pamali). Apa makna di balik mitos "keramat" tersebut? Secara ekologis (ilmu lingkungan), ini adalah cara cerdas leluhur untuk melindungi sumber mata air desa dari kekeringan dan mencegah tanah longsor. Tanpa perlu belajar sains modern, mereka sudah tahu cara melakukan konservasi alam!'),
      MateriBlock(MateriBlockType.heading, 'Peran Tradisi, Kearifan Lokal, dan Budaya dalam Masyarakat Global'),
      MateriBlock(MateriBlockType.paragraph, 'Mengapa kita harus repot-repot melestarikan semua ini di saat dunia sudah memiliki teknologi AI, smartphone, dan kebudayaan pop yang seragam? Berikut adalah peran krusial budaya lokal di kancah global:'),
      MateriBlock(MateriBlockType.numberedItem, '1. Filter (Penyaring) Budaya Asing'),
      MateriBlock(MateriBlockType.paragraph, 'Arus globalisasi membawa banyak nilai yang tidak selalu cocok dengan karakter bangsa kita (seperti gaya hidup bebas tanpa aturan, individualisme ekstrem, atau materialisme). Kearifan lokal berfungsi sebagai "saringan". Kita boleh mengambil teknologi dan ilmu pengetahuan dari Barat, tetapi kita tetap menjunjung tinggi sopan santun, religiusitas, dan kekeluargaan khas Indonesia.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Solusi untuk Krisis Global'),
      MateriBlock(MateriBlockType.paragraph, 'Dunia saat ini sedang pusing menghadapi Pemanasan Global (Global Warming). Negara-negara maju kini mulai menoleh ke kearifan lokal masyarakat adat untuk mencari solusi. Contoh: Tradisi Sasi di Maluku dan Papua yang melarang penangkapan ikan pada bulan-bulan tertentu, kini diakui secara global sebagai cara paling efektif untuk mencegah kepunahan biota laut.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Kekuatan Soft Power dan Diplomasi'),
      MateriBlock(MateriBlockType.paragraph, 'Korea Selatan menaklukkan dunia tidak dengan senjata atau militer, melainkan dengan soft power (K-Pop, K-Drama, dan kosmetik). Indonesia pun bisa! Batik telah menjadi pakaian diplomasi internasional. Gamelan diajarkan di berbagai universitas top di Amerika Serikat dan Eropa. Budaya adalah senjata paling damai untuk membuat negara kita dihormati di mata dunia.'),
      MateriBlock(MateriBlockType.numberedItem, '4. Penggerak Ekonomi Kreatif'),
      MateriBlock(MateriBlockType.paragraph, 'Candi Borobudur, Desa Adat Penglipuran di Bali, atau kain Tenun Sumba bukan sekadar pajangan sejarah. Mereka adalah roda penggerak ekonomi (pariwisata). Jutaan turis datang untuk melihat keaslian budaya kita, bukan untuk melihat gedung pencakar langit (karena di negara mereka jauh lebih megah).'),
      MateriBlock(MateriBlockType.heading, 'Komitmen Menjaga dan Melestarikan Tradisi'),
      MateriBlock(MateriBlockType.paragraph, 'Kamu mungkin berpikir, "Saya kan masih SMP, memangnya apa yang bisa saya lakukan untuk melestarikan budaya yang besar ini?" Melestarikan budaya tidak harus selalu dengan menjadi seniman maestro. Sebagai bagian dari masyarakat global, kamu bisa melakukan Gaklokalisasi (berpikir Global, bertindak Lokal). Berikut adalah komitmen nyata yang bisa kamu terapkan:'),
      MateriBlock(MateriBlockType.bullet, 'Cultural Experience (Terlibat Langsung)'),
      MateriBlock(MateriBlockType.paragraph, 'Jangan hanya tahu nama tariannya, tapi cobalah mempraktikkannya. Ikutilah ekstrakurikuler kesenian di sekolah. Cicipi makanan tradisional dari berbagai daerah (jangan hanya makan ayam fast-food). Pengalaman langsung akan menumbuhkan rasa cinta.'),
      MateriBlock(MateriBlockType.bullet, 'Cultural Knowledge (Memahami Maknanya)'),
      MateriBlock(MateriBlockType.paragraph, 'Ketika kamu memakai Batik, carilah tahu apa nama motifnya dan maknanya (misal: motif Mega Mendung melambangkan keteduhan hati). Ketika kamu mengetahui sejarah di balik suatu benda budaya, kamu tidak akan mudah terpengaruh saat negara lain mencoba mengklaimnya.'),
      MateriBlock(MateriBlockType.bullet, 'Memanfaatkan Teknologi dan Media Sosial'),
      MateriBlock(MateriBlockType.paragraph, 'Di sinilah kekuatan terbesarmu. Gunakan akun TikTok, Instagram, atau YouTube milikmu untuk memperkenalkan budaya daerahmu. Kamu bisa membuat video transisi make-up menggunakan pakaian adat, membuat vlog jalan-jalan ke pasar tradisional, atau me-remix lagu daerah dengan iringan musik modern. Jadikan budayamu trending topic.'),
      MateriBlock(MateriBlockType.bullet, 'Menolak Cultural Appropriation (Pencurian/Eksploitasi Budaya)'),
      MateriBlock(MateriBlockType.paragraph, 'Kita harus kritis menjaga hak cipta budaya kita. Jika ada produk luar negeri yang mengambil motif tradisional kita tanpa memberikan kredit atau merendahkan maknanya, kita harus berani bersuara (tentunya dengan cara yang beradab) di forum-forum global.'),
      MateriBlock(MateriBlockType.bullet, 'Bangga Memakai Produk Lokal'),
      MateriBlock(MateriBlockType.paragraph, 'Pilihlah sepatu, tas, atau pakaian hasil karya UMKM lokal yang menginkorporasikan elemen budaya, seperti jaket dengan aksen tenun atau tas dari anyaman rotan. Bangga memakainya di tongkrongan adalah langkah terkecil namun paling berdampak.'),
      MateriBlock(MateriBlockType.paragraph, 'Jati diri bangsa tidak diukur dari seberapa banyak gedung tinggi yang kita bangun, tetapi dari seberapa kuat kita berpijak pada akar sejarah kita. Jadilah generasi global yang fasih berbahasa Inggris, jago coding, namun tetap santun dan bangga menjadi orang Indonesia.'),
    ],
  ),
  MateriSection(
    id: 'kelas9-materi-5',
    number: 5,
    title: 'Menjaga Keutuhan Wilayah Negara Kesatuan Republik Indonesia',
    summary: 'Bayangkan Indonesia sebagai sebuah kapal pesiar raksasa bernama "Nusantara". Kapal ini berlayar di samudra luas, membawa lebih dari 270 juta penumpang yang berasal dari ratusan suku, ras, dan agama yang berbeda. Jika ada sekelompok orang yang melubangi lambung kapal, entah karena egois, bertengkar, atau tidak peduli, maka yang tenggelam bukan hanya kelompok itu saja, melainkan seluruh kapal.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.paragraph, 'Menjaga kapal Nusantara agar tetap utuh dan berlayar mencapai tujuan (kesejahteraan dan keadilan sosial) adalah tugas seluruh penumpangnya, termasuk kamu yang saat ini duduk di bangku kelas IX SMP. Mari kita bedah bagaimana cara kita menjaga kapal raksasa ini agar tidak tenggelam atau terbelah.'),
      MateriBlock(MateriBlockType.heading, 'Komitmen untuk Menjaga Keutuhan Wilayah Negara Kesatuan Republik Indonesia (NKRI)'),
      MateriBlock(MateriBlockType.paragraph, 'Komitmen bukanlah sekadar janji yang diucapkan saat upacara bendera, melainkan tekad kuat yang diwujudkan dalam tindakan nyata secara terus-menerus. Mengapa kita harus berkomitmen mempertahankan NKRI? Secara geografis, Indonesia adalah negara kepulauan (archipelagic state) terbesar di dunia. Ribuan pulau yang dipisahkan oleh lautan sangat rentan untuk terpecah belah. Oleh karena itu, para pendiri bangsa telah mengunci komitmen ini dalam UUD NRI Tahun 1945 Pasal 37 Ayat (5) yang berbunyi: "Khusus mengenai bentuk Negara Kesatuan Republik Indonesia tidak dapat dilakukan perubahan."'),
      MateriBlock(MateriBlockType.paragraph, 'Ini adalah satu-satunya pasal dalam konstitusi kita yang diharamkan untuk diamandemen. Artinya, mau seberapa maju teknologi kita nanti, atau siapa pun presidennya, bentuk negara kita harus tetap Kesatuan, bukan negara serikat atau federal yang bisa memisahkan diri sewaktu-waktu. Komitmen ini tidak muncul tiba-tiba. Jauh sebelum Indonesia merdeka, pemuda-pemuda dari Jong Java, Jong Ambon, Jong Sumatranen Bond, dan lainnya sudah menyadari hal ini. Mereka membuang ego kesukuan mereka dan bersumpah dalam Sumpah Pemuda 1928: Bertumpah darah satu, berbangsa satu, dan menjunjung bahasa persatuan, Indonesia. Semangat inilah yang menjadi pondasi awal mengapa NKRI harus dipertahankan hingga titik darah penghabisan.'),
      MateriBlock(MateriBlockType.heading, 'Upaya Mempertahankan Kesatuan dan Persatuan Negara Kesatuan Republik Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Mempertahankan kesatuan bukan hanya tugas Tentara Nasional Indonesia (TNI) atau Kepolisian (Polri) di perbatasan. Negara menggunakan pendekatan menyeluruh yang disebut ketahanan nasional, yang mencakup berbagai bidang:'),
      MateriBlock(MateriBlockType.bullet, 'Bidang Ideologi: Menanamkan nilai-nilai Pancasila sejak dini melalui pendidikan. Pancasila adalah "lem" yang merekatkan berbagai perbedaan di Indonesia. Tanpa Pancasila, kelompok mayoritas akan menindas minoritas, dan negara akan hancur.'),
      MateriBlock(MateriBlockType.bullet, 'Bidang Politik: Melaksanakan pemilihan umum secara damai dan demokratis. Persatuan akan terjaga jika rakyat merasa suaranya dihargai dan pemimpin tidak bertindak semena-mena.'),
      MateriBlock(MateriBlockType.bullet, 'Bidang Ekonomi (Pembangunan Merata): Dulu, pembangunan sering kali hanya berpusat di Pulau Jawa (Jawa-sentris). Akibatnya, daerah-daerah di luar Jawa merasa dianaktirikan dan muncul bibit-bibit ingin memisahkan diri. Kini, upaya mempertahankan NKRI dilakukan dengan membangun infrastruktur (seperti Jalan Trans-Papua, bendungan di NTT, dan pelabuhan di berbagai pulau terluar) agar keadilan sosial benar-benar dirasakan oleh seluruh rakyat.'),
      MateriBlock(MateriBlockType.bullet, 'Bidang Sosial Budaya: Menghargai kebudayaan daerah lain dan menjadikannya sebagai kekayaan nasional, bukan alat untuk menyombongkan suku sendiri (etnosentrisme).'),
      MateriBlock(MateriBlockType.heading, 'Tantangan dalam Upaya Mempertahankan Wilayah Negara Kesatuan Republik Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Semakin besar sebuah negara, semakin besar pula angin yang menerpanya. Tantangan yang dihadapi NKRI hari ini jauh lebih kompleks dibandingkan saat zaman penjajahan Belanda. Musuh kita sekarang bukan lagi pasukan bersenjata yang terlihat jelas, melainkan tantangan yang berasal dari dalam dan luar negeri.'),
      MateriBlock(MateriBlockType.numberedItem, '1. Tantangan Internal (Dari Dalam Negeri)'),
      MateriBlock(MateriBlockType.paragraph, 'Tantangan dari dalam justru sering kali lebih berbahaya karena bisa memicu perang saudara.'),
      MateriBlock(MateriBlockType.bullet, 'Ancaman Separatisme: Masih adanya kelompok-kelompok yang ingin memisahkan diri dari NKRI melalui pemberontakan bersenjata, seperti Kelompok Kriminal Bersenjata (KKB) di Papua. Mereka memanfaatkan isu ketidakadilan masa lalu untuk melakukan kekerasan yang memakan korban jiwa warga sipil dan aparat.'),
      MateriBlock(MateriBlockType.bullet, 'Intoleransi dan Radikalisme: Munculnya kelompok-kelompok ekstrem yang memaksakan kehendak dan tidak bisa menerima perbedaan agama atau pandangan. Mereka kerap menyebarkan kebencian yang merusak kerukunan umat beragama.'),
      MateriBlock(MateriBlockType.bullet, 'Penyebaran Hoaks dan Ujaran Kebencian: Di era media sosial, sebuah berita bohong (hoaks) yang menyinggung Suku, Agama, Ras, dan Antargolongan (SARA) bisa viral dalam hitungan menit dan memicu kerusuhan berdarah di dunia nyata.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Tantangan Eksternal (Dari Luar Negeri)'),
      MateriBlock(MateriBlockType.bullet, 'Sengketa Perbatasan: Wilayah laut dan pulau-pulau terluar Indonesia yang kaya akan sumber daya alam sering kali diklaim oleh negara tetangga. Contoh paling nyata adalah ketegangan di perairan Natuna Utara, di mana kapal-kapal nelayan asing yang dikawal coast guard negara mereka secara ilegal mengambil ikan di Zona Ekonomi Eksklusif (ZEE) Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Invasi Budaya (Neokolonialisme): Penjajahan gaya baru. Negara asing tidak menjajah tanah kita, tetapi menjajah pikiran generasi muda melalui budaya pop, gaya hidup materialistis, dan individualisme yang mengikis jiwa gotong royong bangsa Indonesia.'),
      MateriBlock(MateriBlockType.heading, 'Menumbuhkan Kesadaran untuk Menjaga Keutuhan Negara Kesatuan Republik Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Kesadaran tidak bisa dipaksakan; ia harus ditumbuhkan dari dalam hati. Bagaimana caranya agar generasi muda memiliki kesadaran otomatis untuk membela dan menjaga NKRI?'),
      MateriBlock(MateriBlockType.bullet, 'Memahami Sejarah Darah dan Airmata: Kesadaran akan muncul ketika kamu menyadari bahwa kemerdekaan ini tidak diberikan gratis. Jutaan pahlawan gugur agar kamu bisa sekolah dengan tenang hari ini. Membaca dan menonton dokumenter sejarah akan menumbuhkan rasa empati dan utang budi pada negara.'),
      MateriBlock(MateriBlockType.bullet, 'Meningkatkan Literasi Digital: Sadar bahwa ruang digital (internet) adalah medan perang modern. Dengan memiliki literasi digital yang baik, kamu tidak akan mudah diaduk-aduk emosinya oleh narasi provokatif di TikTok atau Instagram yang sengaja dibuat untuk memecah belah bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Mengembangkan Sikap Nasionalisme Rasional: Nasionalisme yang ditumbuhkan bukan lagi "nasionalisme buta" yang menganggap negara sendiri paling benar, melainkan nasionalisme yang rasional. Yaitu mencintai negara dengan cara memperbaiki kekurangannya, taat membayar pajak (kelak saat sudah bekerja), dan mengkritik kebijakan pemerintah yang salah melalui jalur yang beradab.'),
      MateriBlock(MateriBlockType.heading, 'Peran Aktif Peserta Didik dalam Menjaga Keutuhan Wilayah Negara Kesatuan Republik Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Menjaga NKRI bukanlah tugas yang harus menunggu kamu menjadi presiden atau jenderal tentara. Sebagai siswa SMP Kelas IX, kamu sudah berada di garis depan pertahanan negara melalui tindakan-tindakan nyata di kehidupan sehari-hari:'),
      MateriBlock(MateriBlockType.bullet, 'Menghancurkan Rantai Bullying (Perundungan): Bullying berdasarkan fisik, suku, atau agama di sekolah adalah bibit dari perpecahan bangsa. Dengan berani membela teman yang ditindas dan menciptakan ruang kelas yang aman bagi semua orang, kamu sedang mempraktikkan sila ke-2 dan ke-3 Pancasila.'),
      MateriBlock(MateriBlockType.bullet, 'Menjadi Agen Saring Sebelum Sharing: Jangan jadikan jarimu sebagai senjata pemusnah massal. Jika menerima informasi panas di grup WhatsApp kelas atau FYP yang memojokkan kelompok tertentu, jangan langsung diteruskan (forward). Cari tahu dulu kebenarannya. Memutus rantai hoaks adalah bentuk bela negara di era digital.'),
      MateriBlock(MateriBlockType.bullet, 'Berprestasi Membawa Nama Harum Bangsa: Bela negara bagi seorang pelajar adalah belajar dengan sungguh-sungguh. Memenangkan olimpiade sains, kejuaraan olahraga, atau festival seni di tingkat nasional maupun internasional akan meningkatkan martabat NKRI di mata dunia.'),
      MateriBlock(MateriBlockType.bullet, 'Bergabung dalam Organisasi Kepemudaan: Aktif di Pramuka, OSIS, Paskibra, atau PMR melatih kedisiplinan, kepemimpinan, dan kerjasama tim yang lintas latar belakang. Di sinilah kamu belajar berorganisasi layaknya mengatur sebuah miniatur negara.'),
      MateriBlock(MateriBlockType.bullet, 'Mencintai dan Menggunakan Produk Dalam Negeri: Membeli sepatu buatan pabrik lokal di Bandung atau menggunakan tas kreasi UMKM daerahmu berarti kamu menyelamatkan lapangan pekerjaan bagi rakyat Indonesia. Ekonomi yang kuat akan membuat negara tidak mudah diombang-ambingkan oleh kekuatan asing.'),
      MateriBlock(MateriBlockType.paragraph, 'Keutuhan NKRI bukanlah sesuatu yang turun dari langit, melainkan hasil dari keringat dan kedisiplinan setiap warga negaranya. Setiap kali kamu memilih untuk menghargai teman yang berbeda agama, membuang sampah pada tempatnya, dan menolak menyebarkan kebencian di media sosial, kamu sedang memegang teguh tali persatuan yang menjaga kapal Nusantara ini tetap berlayar gagah mengarungi tantangan zaman.'),
    ],
  ),
];
